import math

def solve(graph):
    total_cost = 0
    while True:
        n = len(graph)
        if n == 1:
            break
        x = random.choice(range(n))
        total_cost += n
        del graph[x]
        unique_components = set()
        while graph:
            removed = graph.pop(random.choice(range(len(graph))))
            if removed in unique_components:
                continue
            component = []
            while removed in graph:
                component.append(removed)
                if len(graph[removed]) == 1:
                    del graph[removed]
                else:
                    del graph[removed][graph[removed].index(removed)]
                unique_components.add(removed)
            total_cost -= 1
            yield component

def compute_expectation(n):
    total_cost = 0
    successes = 0
    for _ in range(100000):
        graph = [set([i]) for i in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                graph[i].add(j)
                graph[j].add(i)
        for _ in solve(graph):
            total_cost += 1
            if random.choice(range(1000000)) == 499999:
                successes += 1
    return total_cost / successes

