import sys
from typing import List, Tuple

def shortest_route(n: int, m: int, roads: List[Tuple[int, int]]) -> Tuple[int, List[int], List[int]]:
    # Implement the Floyd-Warshall algorithm in the routing graph to find the shortest path
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if (i, j) in roads and ((i, k) in roads or (k, j) in roads):
                    roads[(i, j)] = min(roads[(i, j)], (i, k) in roads + (k, j) in roads)

    # Helper function to find the shortest path
    def find_route(start: int, end: int, mode: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        routes = {}
        visited = [False] * (n + 1)
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            if mode and node == start:
                routes[node], start = (end,), node
                break
            for neighbor in mode[node]:
                if neighbor not in visited:
                    visited[neighbor] = True
                    queue.append(neighbor)
                    if node < end:
                        routes[node], neighbor = (neighbor,), node
        return routes

    # Find Bob's and Alex's routes
    bob, alice = find_route(1, n, roads), find_route(n, 1, reversed(roads))
    bob.nodes, alice.nodes = alice.nodes + 1, bob.nodes + 1

    # Filter routes with at least one intersection, priority from shorter to longer paths
    filter_routes = [path for path in zip(bob.nodes, alice.nodes) if sum(map(False, path)) != 2 and len(path) > 1]

    # Choose the optimal route
    best_length, best_sequence = 2**30, [-1, -1]
    for path in filter_routes:
        k = path_count[0] + path_count[1]
        if k < best_length:
            best_length = k
            best_sequence = path

    return best_length, best_sequence[0], best_sequence[1]

