from collections import defaultdict, deque

def max_xor_in_path(n, graph):
    def shortest_path(d, x, y):
        if len(d) == n:
            return d
        queue = deque([(0, [x])])
        visited = set([x])
        while queue:
            dist, path = queue.popleft()
            for node in graph[dist]:
                if node not in visited:
                    visited.add(node)
                    queue.append((node, path + [node]))
                    if node == y:
                        return path
        return None

    answer = [0] * (1 << n)
    for i in range(n):
        answer[i] = 1 << i
    for i in range(n - 1):
        x, y, w = i, n - 1 + i, long(input().strip())
        for j in range(1 << n):
            answer[j] = max(answer[j^(1 << x) | (1 << y)], answer[j])
        for j in range(1 << n):
            if shortest_path(answer, x, y):
                for i in shortest_path(answer, x, y):
                    answer[i] = max(answer[i], j ^ w)
    return max(answer)

