from collections import defaultdict

def find_shortest_route(n, m, roads):
    connections = defaultdict(list)
    for road in roads:
        connections[road[0]].append(road[1])
        connections[road[1]].append(road[0])

    def check_route(connect, length, flag):
        for i in range(1, length + 1):
            if i % 2 == 0:
                if connect[0] not in connections[connect[length - i]] or flag and connect[length - i] in connections[connect[0]]:
                    return False
                connect[length - i] = connect[0]
            else:
                if connect[length - i] not in connections[connect[length - i + 1]] or flag and connect[length - i + 1] in connections[connect[length - i]]:
                    return False
                connect[length - i + 1] = connect[length - i]
        return True

    def dfs(start, end):
        nonlocal min_length, shortest_route, visited
        if start == end:
            if len(shortest_route) > 1 and check_route(shortest_route, len(shortest_route), True):
                min_length = min(min_length, len(shortest_route))
                shortest_route = shortest_route.copy()
            return
        visited[start] = True
        for neighbor in connections[start]:
            if not visited[neighbor] and neighbor != end:
                dfs(neighbor, end)
        visited[start] = False

    visited = [False] * (n + 2)  # Include start, middle and end positions
    min_length = float('inf')
    shortest_route = []
    dfs(1, n)
    if min_length == float('inf'):
        return -1
    else:
        return min_length, shortest_route[n:], shortest_route

