def calculate_max_sum(max_f, n):
    if n == 0:
        return 0
    elif n == 1:
        return max_f[0]
    elif n == 2:
        return max_f[0] + max_f[4]
    elif n == 3:
        return max_f[1] + max_f[3]
    elif n == 7:
        return max_f[2] + max_f[7]
    elif n == 8:
        return max_f[1] + max_f[3] + max_f[4] + max_f[9]
    elif n == 9:
        return max_f[1] + max_f[7]
    else:
        base, rem = divmod(n - 6, 9)
        if base == 0 or n < 6:
            return rem * max_f[rem]
        base_mid, rem_mid = divmod(base - 1, 2)
        extra = max_f[base_mid + 1] + max_f[base_mid] + max_f[base] - rem_mid * max_f[rem]
        base_left = n - base + 6 * rem_mid - 3
        base_right = 6 * rem_mid - 3
        return extra + max(f(i) + max(f(i) + f(j) for j in range(0, i + 2, 2)) for i in range(base_left, base_right + 2, 4))

